public int MaxProfit(int[] prices) {
    int minPrice = int.MaxValue, best = 0;
    foreach (int p in prices) {
        minPrice = Math.Min(minPrice, p);       // лучшая покупка до сегодня включительно
        best = Math.Max(best, p - minPrice);    // продать сегодня
    }
    return best;
}

