public bool CanJump(int[] nums) {
    int reach = 0;                               // самая дальняя достижимая клетка
    for (int i = 0; i < nums.Length; i++) {
        if (i > reach) return false;             // до i не добраться — и дальше тоже
        reach = Math.Max(reach, i + nums[i]);
    }
    return true;
}

