public int MaxSubArray(int[] nums) {
    int cur = nums[0], best = nums[0];             // непустой: старт с первого, а не с 0
    for (int i = 1; i < nums.Length; i++) {
        cur = Math.Max(nums[i], cur + nums[i]);    // начать заново или продолжить
        best = Math.Max(best, cur);
    }
    return best;
}
