public int Jump(int[] nums) {                    // до конца допрыгнуть можно
    int jumps = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i < nums.Length - 1; i++) {
        farthest = Math.Max(farthest, i + nums[i]);
        if (i == curEnd) {                       // клетки с этим числом прыжков кончились
            jumps++;
            curEnd = farthest;                   // следующий слой — докуда дотянулись
        }
    }
    return jumps;
}
// [2, 3, 1, 1, 4]: i = 0 → 1 прыжок, граница 2; i = 2 → 2 прыжка, граница 4 — ответ 2
